		err := fmt.Errorf("%w: %s", ErrInvalidParam, msg)
		if requestID != "" {
			s.mu.Lock()
			if _, ok := s.requests[requestID]; ok {
				s.appendHistoryLocked(requestID, &HistoryEntry{
					CommitmentID: commitID,
					PartID:       partID,
					Quantity:     quantity,
					Expiry:       expiry,
					SubmittedAt:  now,
					Outcome:      HistoryInvalidParam,
				})
			}
			s.mu.Unlock()
		}
		return Commitment{}, err
	}
	if commitID == "" || requestID == "" || partID == "" {
		return invalid("commit/request/part id must not be empty")
	}
	if quantity <= 0 {
		return invalid("reserve quantity must be a positive integer")
	}
	if !expiry.After(now) {
		return invalid("expiry must be after current time")
	}

	s.mu.Lock()
	defer s.mu.Unlock()

	if existing, ok := s.commitments[commitID]; ok {
		if existing.RequestID != requestID || existing.PartID != partID ||
