					CommitmentID: commitID,
					PartID:       partID,
					Quantity:     quantity,
					Expiry:       expiry,
					SubmittedAt:  now,
					Outcome:      HistoryConflict,
				})
			}
			return Commitment{}, fmt.Errorf("%w: commit id %q reused with different content", ErrConflict, commitID)
		}
		// 同编号同内容的成功重试：沿用已有行为，不追加历史、不重复占用。
