		s.appendHistoryLocked(requestID, &HistoryEntry{
			CommitmentID: commitID,
			PartID:       partID,
			Quantity:     quantity,
			Expiry:       expiry,
			SubmittedAt:  now,
			Outcome:      historyOutcomeFor(eligErr),
