		// 备件缺失：库存依据明确为空，不能用零库存代替缺失。
		s.appendHistoryLocked(requestID, &HistoryEntry{
			CommitmentID: commitID,
			PartID:       partID,
			Quantity:     quantity,
			Expiry:       expiry,
			SubmittedAt:  now,
			Outcome:      HistoryNotFound,
			Eligibility:  eligSnap,
		})
		return Commitment{}, fmt.Errorf("%w: part %q", ErrNotFound, partID)
	}
	if !elig.Eligible {
		s.appendHistoryLocked(requestID, &HistoryEntry{
			CommitmentID: commitID,
			PartID:       partID,
			Quantity:     quantity,
			Expiry:       expiry,
			SubmittedAt:  now,
			Outcome:      HistoryIneligible,
			Eligibility:  eligSnap,
			Stock:        basis,
		})
		return Commitment{}, fmt.Errorf("%w: %v", ErrIneligible, elig.Reasons)
	}
