func TestReservationHistoryFailedCommitIDReusableAndFailuresKept(t *testing.T) {
	s := newStore(t)
	// c1 先因过保失败，编号未被占用。
	if _, err := s.Reserve("c1", "r1", "part1", 1, expiryOK, t0.Add(31*day)); !errors.Is(err, ErrIneligible) {
