	}

	s2 := newStore(t)
	mustReserve(t, s2, "c1", "r1", "part1", 5, expiryOK, nowOK)
	if _, err := s2.Use("u1", "c1", 2, expiryOK.Add(-time.Second)); err != nil {
		t.Fatalf("use before expiry: %v", err)
	}
	// 到期后：承诺失效、余量释放。
	st2, _ := s2.PartStatus("part1", expiryOK)
