	h2, _ := s2.ReservationHistory("r1")
	e2 := h2[0]
	if e2.Quantity != 5 || e2.Stock.PhysicalRemaining != 10 || e2.Stock.ActiveOccupied != 0 || e2.Stock.Committable != 10 {
		t.Fatalf("basis changed after expiry: qty=%d stock=%+v", e2.Quantity, e2.Stock)
	}
}

