7	)
8	
9	// activeOccupiedLocked 返回某备件在指定当前时刻的有效承诺未用总量。
10	// 已取消或已到期的承诺不计入占用。
11	func (s *Store) activeOccupiedLocked(partID string, now time.Time) int {
12		total := 0
13		for _, c := range s.commitments {
14			if c.PartID != partID {
15				continue
16			}
17			if c.Canceled || !now.Before(c.Expiry) {
18				continue
19			}
20			total += c.Quantity - c.Used
21		}
22		return total
23	}
24	
25	// cloneEligibilityLocked 返回资格依据的独立副本，拒绝原因切片也一并复制，
26	// 使保存进历史的快照不与任何返回给调用方的对象共享底层数组。
27	func cloneEligibilityLocked(e *Eligibility) *Eligibility {
28		cp := *e
29		if e.Reasons != nil {
30			cp.Reasons = append([]RejectionReason(nil), e.Reasons...)
31		}
32		return &cp
33	}
34	
35	// Reserve 为请求预留一种备件，数量为正整数，到期时刻必须晚于当前时刻。
36	// 每次预留都按当次时刻重新判断资格；可承诺数量等于剩余实物库存扣除所有
37	// 有效承诺的未用数量。库存不足、未知请求或备件、不合格请求都不占用数量。
38	//
39	// 提交编号全局唯一：相同编号且相同内容的重试返回同一承诺；换请求、备件、
40	// 数量或到期时刻则返回 ErrConflict。
41	//
42	// 对已登记的请求，首次预留成功及每次失败提交都会在该请求的预留历史中
43	// 留下记录，快照本次提交时刻的资格依据与处理前的库存依据；同编号同内容的
44	// 成功重试不追加记录、不重复占用。冲突失败记录挂在本次提交指定的已知请求下
45	// （编号原本属于另一请求时也不例外）。未知请求的提交不创建请求，也不留历史。
46	func (s *Store) Reserve(commitID, requestID, partID string, quantity int, expiry, now time.Time) (Commitment, error) {
47		// 参数校验与原实现一致，按编号、数量、到期时刻的次序取第一项错误。
48		invalidMsg := ""
49		switch {
50		case commitID == "" || requestID == "" || partID == "":
51			invalidMsg = "commit/request/part id must not be empty"
52		case quantity <= 0:
53			invalidMsg = "reserve quantity must be a positive integer"
54		case !expiry.After(now):
55			invalidMsg = "expiry must be after current time"
56		}
57	
58		s.mu.Lock()
59		defer s.mu.Unlock()
60	
61		if invalidMsg != "" {
62			// 参数无效：仅当请求已登记时在该请求下留记录，依据明确为空。
63			if requestID != "" {
64				if _, ok := s.requests[requestID]; ok {
65					s.appendHistoryLocked(requestID, &HistoryEntry{
66						CommitmentID: commitID,
67						PartID:       partID,
68						Quantity:     quantity,
69						Expiry:       expiry,
70						SubmittedAt:  now,
71						Outcome:      HistoryInvalidParam,
72					})
73				}
74			}
75			return Commitment{}, fmt.Errorf("%w: %s", ErrInvalidParam, invalidMsg)
76		}
77	
78		if existing, ok := s.commitments[commitID]; ok {
79			if existing.RequestID != requestID || existing.PartID != partID ||
80				existing.Quantity != quantity || !existing.Expiry.Equal(expiry) {
81				// 冲突失败记录挂在本次提交指定的已知请求下；该请求未知时按原约定报错且不留历史。
82				if _, reqKnown := s.requests[requestID]; reqKnown {
83					s.appendHistoryLocked(requestID, &HistoryEntry{
84						CommitmentID: commitID,
85						PartID:       partID,
86						Quantity:     quantity,
87						Expiry:       expiry,
88						SubmittedAt:  now,
89						Outcome:      HistoryConflict,
90					})
91				}
92				return Commitment{}, fmt.Errorf("%w: commit id %q reused with different content", ErrConflict, commitID)
93			}
94			// 同编号同内容的成功重试：沿用已有行为，不追加历史、不重复占用。
95			return *existing, nil
96		}
97	
98		req, ok := s.requests[requestID]
99		if !ok {
100			// 未知请求不创建请求，也不创建历史。
101			return Commitment{}, fmt.Errorf("%w: request %q", ErrNotFound, requestID)
102		}
103	
104		entry := &HistoryEntry{
105			CommitmentID: commitID,
106			PartID:       partID,
107			Quantity:     quantity,
108			Expiry:       expiry,
109			SubmittedAt:  now,
110		}
111		part, partKnown := s.parts[partID]
112		if !partKnown {
113			// 备件缺失（原实现先于资格判断）：资格与库存依据都明确为空，
114			// 不能用合格或零库存代替缺失。
115			entry.Outcome = HistoryNotFound
116			s.appendHistoryLocked(requestID, entry)
117			return Commitment{}, fmt.Errorf("%w: part %q", ErrNotFound, partID)
118		}
119	
120		elig, err := s.evaluateLocked(req, now)
121		if err != nil {
122			// 缺少产品（或故障代码缺失）：依据无法计算，资格与库存依据留空。
123			if errors.Is(err, ErrNotFound) {
124				entry.Outcome = HistoryNotFound
125			} else {
126				entry.Outcome = HistoryInvalidParam
127			}
128			s.appendHistoryLocked(requestID, entry)
129			return Commitment{}, err
130		}
131	
132		// 资格可算且备件存在：成功、不合格、库存不足三种结果都保存完整依据。
133		entry.Eligibility = cloneEligibilityLocked(elig)
134		basis := &StockBasis{
135			PhysicalRemaining: part.Stock,
136			ActiveOccupied:    s.activeOccupiedLocked(partID, now),
137		}
138		basis.Committable = basis.PhysicalRemaining - basis.ActiveOccupied
139		entry.Stock = basis
140	
141		if !elig.Eligible {
142			entry.Outcome = HistoryIneligible
143			s.appendHistoryLocked(requestID, entry)
144			return Commitment{}, fmt.Errorf("%w: %v", ErrIneligible, elig.Reasons)
145		}
146		if quantity > basis.Committable {
147			entry.Outcome = HistoryInsufficientStock
148			s.appendHistoryLocked(requestID, entry)
149			return Commitment{}, fmt.Errorf("%w: need %d, committable %d", ErrInsufficientStock, quantity, basis.Committable)
150		}
151	
152		c := &Commitment{
153			ID:        commitID,
154			RequestID: requestID,
155			PartID:    partID,
156			Quantity:  quantity,
157			Expiry:    expiry,
158		}
159		s.commitments[commitID] = c
160		entry.Outcome = HistorySucceeded
161		s.appendHistoryLocked(requestID, entry)
162		return *c, nil
163	}
164	
165	// Use 使用一笔承诺，数量为正整数，分批扣减该承诺未用数量和剩余实物库存。
166	// 数量超过未用数量时整次失败，不改变任何记录。
167	//
168	// 使用编号全局唯一：相同编号且相同内容的重试返回首次成功结果，不再次扣减；
169	// 改数量或改承诺返回 ErrConflict。已经成功的使用在承诺取消或到期后重试，
170	// 仍返回原结果。已全部使用的承诺不再接受新使用。
171	func (s *Store) Use(usageID, commitID string, quantity int, now time.Time) (Usage, error) {
172		if usageID == "" || commitID == "" {
173			return Usage{}, fmt.Errorf("%w: usage/commit id must not be empty", ErrInvalidParam)
174		}
175		if quantity <= 0 {
176			return Usage{}, fmt.Errorf("%w: usage quantity must be a positive integer", ErrInvalidParam)
177		}
178		s.mu.Lock()
179		defer s.mu.Unlock()
180	
181		if existing, ok := s.usages[usageID]; ok {
182			if existing.CommitmentID != commitID || existing.Quantity != quantity {
183				return Usage{}, fmt.Errorf("%w: usage id %q reused with different content", ErrConflict, usageID)
184			}
185			return *existing, nil
186		}
187	
188		c, ok := s.commitments[commitID]
189		if !ok {
190			return Usage{}, fmt.Errorf("%w: commitment %q", ErrNotFound, commitID)
191		}
192		if c.Canceled {
193			return Usage{}, fmt.Errorf("%w: commitment %q is canceled", ErrCommitmentClosed, commitID)
194		}
195		if !now.Before(c.Expiry) {
196			return Usage{}, fmt.Errorf("%w: commitment %q expired at %v", ErrCommitmentClosed, commitID, c.Expiry)
197		}
198		if quantity > c.Quantity-c.Used {
199			return Usage{}, fmt.Errorf("%w: need %d, unused %d", ErrUsageExceeded, quantity, c.Quantity-c.Used)
200		}
201	
202		c.Used += quantity
203		s.parts[c.PartID].Stock -= quantity
204		u := &Usage{ID: usageID, CommitmentID: commitID, Quantity: quantity}
205		s.usages[usageID] = u
206		return *u, nil
207	}
208	
209	// Cancel 取消承诺，只释放未用数量，不影响已扣减的实物库存。
210	// 重复取消不增加库存；承诺已到期时余量已自动失效，取消同样不产生变化。
211	// 取消后的承诺不能继续使用。
212	func (s *Store) Cancel(commitID string, now time.Time) (Commitment, error) {
213		if commitID == "" {
214			return Commitment{}, fmt.Errorf("%w: commit id must not be empty", ErrInvalidParam)
215		}
216		s.mu.Lock()
217		defer s.mu.Unlock()
218	
219		c, ok := s.commitments[commitID]
220		if !ok {
221			return Commitment{}, fmt.Errorf("%w: commitment %q", ErrNotFound, commitID)
222		}
223		if !c.Canceled {
224			c.Canceled = true
225		}
226		return *c, nil
227	}
